-- Enterprise WooCommerce / WordPress-class foundation
create table if not exists public.shipping_zones (id uuid primary key default gen_random_uuid(),name text not null,description text,countries text[] not null default array['IN'],states text[] not null default '{}',postal_codes text[] not null default '{}',is_default boolean not null default false,status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.shipping_methods (id uuid primary key default gen_random_uuid(),zone_id uuid not null references public.shipping_zones(id) on delete cascade,name text not null,method_type text not null default 'flat_rate',rate numeric not null default 0,enabled boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.order_fulfillments (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,branch_id uuid not null references public.branches(id),status text not null default 'pending',carrier text,tracking_number text,tracking_url text,packed_at timestamptz,shipped_at timestamptz,delivered_at timestamptz,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.returns (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,customer_user_id uuid not null references public.profiles(id),branch_id uuid not null references public.branches(id),request_number text not null unique default ('RET-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),status text not null default 'requested',reason text,customer_note text,admin_note text,refund_amount numeric not null default 0,requested_at timestamptz not null default now(),resolved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.return_items (id uuid primary key default gen_random_uuid(),return_id uuid not null references public.returns(id) on delete cascade,order_item_id uuid not null references public.order_items(id),quantity integer not null,reason text,resolution text not null default 'refund',created_at timestamptz not null default now());
create table if not exists public.invoices (id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.orders(id) on delete cascade,invoice_number text not null unique,status text not null default 'issued',issued_at timestamptz not null default now(),due_at timestamptz,tax_total numeric not null default 0,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.product_relations (id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,related_product_id uuid not null references public.products(id) on delete cascade,relation_type text not null,sort_order integer not null default 0,enabled boolean not null default true,created_at timestamptz not null default now(),unique(product_id,related_product_id,relation_type));
create table if not exists public.promotions (id uuid primary key default gen_random_uuid(),name text not null,description text,promotion_type text not null,value numeric not null default 0,min_order_value numeric not null default 0,starts_at timestamptz,ends_at timestamptz,usage_limit integer,usage_count integer not null default 0,enabled boolean not null default true,branch_id uuid references public.branches(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.site_pages (id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,excerpt text,content jsonb not null default '{}',status text not null default 'draft',published_at timestamptz,scheduled_at timestamptz,template text not null default 'default',created_by uuid references public.profiles(id),updated_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.site_posts (id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,excerpt text,content jsonb not null default '{}',featured_image_url text,author_user_id uuid references public.profiles(id),status text not null default 'draft',published_at timestamptz,scheduled_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.seo_meta (id uuid primary key default gen_random_uuid(),object_type text not null,object_id uuid,canonical_url text,meta_title text,meta_description text,keywords text,og_title text,og_description text,og_image_url text,robots text not null default 'index,follow',schema_json jsonb not null default '{}',updated_at timestamptz not null default now(),unique(object_type,object_id));
create table if not exists public.nav_menus (id uuid primary key default gen_random_uuid(),name text not null unique,location text not null default 'header',enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.nav_menu_items (id uuid primary key default gen_random_uuid(),menu_id uuid not null references public.nav_menus(id) on delete cascade,parent_id uuid references public.nav_menu_items(id) on delete cascade,label text not null,url text,target text not null default '_self',sort_order integer not null default 0,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.content_revisions (id uuid primary key default gen_random_uuid(),object_type text not null,object_id uuid not null,revision_number integer not null,content jsonb not null default '{}',created_by uuid references public.profiles(id),created_at timestamptz not null default now(),unique(object_type,object_id,revision_number));
create table if not exists public.admin_roles (id uuid primary key default gen_random_uuid(),name text not null unique,description text,is_system boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.admin_permissions (id uuid primary key default gen_random_uuid(),permission_key text not null unique,description text,created_at timestamptz not null default now());
create table if not exists public.admin_role_permissions (role_id uuid not null references public.admin_roles(id) on delete cascade,permission_id uuid not null references public.admin_permissions(id) on delete cascade,primary key(role_id,permission_id));
create table if not exists public.admin_user_roles (user_id uuid not null references public.profiles(id) on delete cascade,role_id uuid not null references public.admin_roles(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,role_id));
create table if not exists public.audit_logs (id uuid primary key default gen_random_uuid(),actor_user_id uuid references public.profiles(id),action text not null,entity_type text,entity_id uuid,branch_id uuid references public.branches(id),details jsonb not null default '{}',created_at timestamptz not null default now());
alter table public.coupons add column if not exists minimum_order_value numeric not null default 0;
alter table public.coupons add column if not exists maximum_discount numeric;
alter table public.coupons add column if not exists per_customer_limit integer;
alter table public.coupons add column if not exists first_order_only boolean not null default false;
alter table public.coupons add column if not exists applies_to text not null default 'all';
alter table public.coupons add column if not exists product_ids uuid[] not null default '{}';
alter table public.coupons add column if not exists category_ids uuid[] not null default '{}';
